mark.keyframes:
@keyframes mark-ckm-combat-academy { 
  0% { opacity: 0; clip-path: inset(0px); filter: brightness(5) contrast(0.5); transform: scale(2.6); }
  3% { opacity: 1; clip-path: inset(0px); filter: brightness(3.4) contrast(0.7) drop-shadow(rgba(200, 16, 46, 0.95) 0.9rem 0px) drop-shadow(rgba(78, 154, 143, 0.85) -0.9rem 0px); transform: scale(1.85) translate(-1rem); }
  7% { opacity: 1; clip-path: inset(0px); filter: brightness(1.8) hue-rotate(-35deg) drop-shadow(rgba(200, 16, 46, 0.9) -0.75rem 0px) drop-shadow(rgba(78, 154, 143, 0.8) 0.75rem 0px); transform: scale(1.42) translate(0.95rem, -0.2rem) skew(3deg); }
  11% { opacity: 1; clip-path: inset(0px 0px 55%); filter: brightness(2.2) drop-shadow(rgba(200, 16, 46, 0.85) 0.5rem 0px); transform: scale(1.25) translate(-0.85rem); }
  15% { opacity: 1; clip-path: inset(48% 0px 0px); filter: brightness(2.2) drop-shadow(rgba(78, 154, 143, 0.8) -0.5rem 0px); transform: scale(1.25) translate(0.85rem); }
  19% { opacity: 1; clip-path: inset(28% 0px 30%); filter: brightness(1.6) hue-rotate(30deg) drop-shadow(rgba(200, 16, 46, 0.7) 0.35rem 0px); transform: scale(1.12) translate(-0.5rem, 0.15rem); }
  24% { opacity: 1; clip-path: inset(0px); filter: brightness(1.3) drop-shadow(rgba(78, 154, 143, 0.6) -0.2rem 0px); transform: scale(1.05) translate(0.25rem); }
  32%, 62% { opacity: 1; clip-path: inset(0px); filter: none; transform: none; }
  66% { opacity: 1; clip-path: inset(0px 0px 60%); filter: brightness(1.8) drop-shadow(rgba(78, 154, 143, 0.8) -0.6rem 0px); transform: translate(0.7rem) skew(-2.5deg); }
  70% { opacity: 1; clip-path: inset(52% 0px 0px); filter: brightness(1.8) hue-rotate(-40deg) drop-shadow(rgba(200, 16, 46, 0.85) 0.6rem 0px); transform: translate(-0.8rem); }
  74% { opacity: 1; clip-path: inset(20% 0px 22%); filter: brightness(2.6) contrast(0.7); transform: scale(1.18) translate(0.3rem); }
  80% { opacity: 0.7; clip-path: inset(0px); filter: brightness(3.4) contrast(0.6); transform: scale(1.45); }
  88%, 100% { opacity: 0; clip-path: inset(0px); filter: brightness(4) contrast(0.5); transform: scale(1.7); }
}

